const wait = ms => new Promise(r => setTimeout(r, ms));

test("debounce keeps the last call", async () => {
  const seen = [];
  const d = debounce(x => seen.push(x), 20);
  d(1); d(2); d(3);
  checkEq(seen, []);
  await wait(40);
  checkEq(seen, [3]);
  d(4);
  await wait(10);
  d(5);
  await wait(40);
  checkEq(seen, [3, 5]);
});

test("debounce cancel", async () => {
  const seen = [];
  const d = debounce(x => seen.push(x), 15);
  d("a");
  d.cancel();
  await wait(30);
  checkEq(seen, []);
});

test("retry until it works", async () => {
  let calls = 0;
  const flaky = async () => { calls++; if (calls < 3) throw new Error(`fail ${calls}`); return "ok"; };
  const t = Date.now();
  checkEq(await retry(flaky, 5, 10), "ok");
  checkEq(calls, 3);
  check(Date.now() - t >= 25, "should wait 10 then 20 ms between attempts");
});

test("retry gives up with the last error", async () => {
  let calls = 0;
  try {
    await retry(async () => { calls++; throw new Error(`fail ${calls}`); }, 3, 1);
    check(false, "should reject");
  } catch (e) {
    checkEq(e.message, "fail 3");
  }
  checkEq(calls, 3);
});

test("mapLimit respects the limit and keeps order", async () => {
  let active = 0, peak = 0;
  const work = async (n, i) => { active++; peak = Math.max(peak, active); await wait(5 + (n % 3) * 5); active--; return `${i}:${n * n}`; };
  checkEq(await mapLimit([1, 2, 3, 4, 5, 6, 7], 3, work), ["0:1", "1:4", "2:9", "3:16", "4:25", "5:36", "6:49"]);
  checkEq(peak, 3);
  checkEq(await mapLimit([], 2, work), []);
});

test("mapLimit stops after an error", async () => {
  const started = [];
  const work = async n => { started.push(n); await wait(10); if (n === 2) throw new Error("two failed"); return n; };
  try {
    await mapLimit([1, 2, 3, 4, 5, 6], 2, work);
    check(false, "should reject");
  } catch (e) {
    checkEq(e.message, "two failed");
  }
  await wait(30);
  check(started.length <= 3, `started ${started.length} items after the error`);
});

